WITH defaults AS (SELECT jsonb_build_array(jsonb_build_object('id','leads-dia','titulo','Leads por dia','tipo','barras_empilhadas','fonte','contato','painel','leads-dia','dimensao',jsonb_build_object('fonte','contato','campo','criado_em')),jsonb_build_object('id','leads-por','titulo','Leads por','tipo','rosca','fonte','contato','painel','leads-por','dimensao',jsonb_build_object('fonte','contato','campo','origem')),jsonb_build_object('id','conversas-dia','titulo','Conversas por dia','tipo','barras_empilhadas','fonte','atendimento','painel','conversas-dia','dimensao',jsonb_build_object('fonte','atendimento','campo','criado_em')),jsonb_build_object('id','campanhas','titulo','Principais campanhas','tipo','barras','fonte','utm','painel','campanhas','dimensao',jsonb_build_object('fonte','utm','campo','campaign')),jsonb_build_object('id','canais','titulo','Atendimentos por canal','tipo','barras','fonte','atendimento','painel','canais','dimensao',jsonb_build_object('fonte','atendimento','campo','canal')),jsonb_build_object('id','atendentes','titulo','Conversas por atendente','tipo','tabela','fonte','atendimento','painel','atendentes','dimensao',jsonb_build_object('fonte','atendimento','campo','atendente'))) AS cards)
UPDATE public.elora_dashboard_visoes v SET filtros = (CASE WHEN jsonb_typeof(v.filtros)='object' THEN v.filtros ELSE '{}'::jsonb END) || jsonb_build_object('cartoes', COALESCE((SELECT jsonb_agg(c) FROM defaults d, jsonb_array_elements(d.cards) c WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v.filtros->'cartoes')='array' THEN v.filtros->'cartoes' ELSE '[]'::jsonb END) e WHERE e->>'id'=c->>'id') AND NOT COALESCE(v.filtros->'cartoesOcultos','[]'::jsonb) ? (c->>'id')), '[]'::jsonb) || CASE WHEN jsonb_typeof(v.filtros->'cartoes')='array' THEN v.filtros->'cartoes' ELSE '[]'::jsonb END, 'painelCartoesMigrado', true)
WHERE v.publicada=true AND COALESCE(v.filtros->>'painelCartoesMigrado','false') <> 'true' AND EXISTS (SELECT 1 FROM public.elora_integracao_contas i WHERE i.cliente_id=v.cliente_id AND COALESCE(i.fonte_dados,'automatica') <> 'antiga') AND EXISTS (SELECT 1 FROM public.elora_sync_estado s WHERE s.cliente_id=v.cliente_id AND s.fonte='contatos' AND s.concluido_em IS NOT NULL);